// SPDX-License-Identifier: MIT
pragma solidity ^0.8.27;

import {ContractRegistry} from "flare-periphery/src/flare/ContractRegistry.sol";
import {IAssetManager} from "flare-periphery/src/flare/IAssetManager.sol";
import {AgentInfo} from "flare-periphery/src/flare/data/AvailableAgentInfo.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IERC165} from "@openzeppelin/contracts/utils/introspection/IERC165.sol";
import {IERC721Receiver} from "@openzeppelin/contracts/token/ERC721/IERC721Receiver.sol";
import {ERC721Holder} from "@openzeppelin/contracts/token/ERC721/utils/ERC721Holder.sol";
import {ERC1155Holder} from "@openzeppelin/contracts/token/ERC1155/utils/ERC1155Holder.sol";
import {IERC1363Receiver} from "@openzeppelin/contracts/interfaces/IERC1363Receiver.sol";
import {ReentrancyGuardTransient} from "@openzeppelin/contracts/utils/ReentrancyGuardTransient.sol";
import {IBeacon} from "@openzeppelin/contracts/proxy/beacon/IBeacon.sol";
import {IIPersonalAccount} from "../interface/IIPersonalAccount.sol";
import {IVaultsFacet} from "../../userInterfaces/facets/IVaultsFacet.sol";
import {IIVault} from "../interface/IIVault.sol";
import {IPersonalAccount} from "../../userInterfaces/IPersonalAccount.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/**
 * @title PersonalAccount contract
 * @notice Account controlled by MasterAccountController contract. It corresponds to an XRPL address.
 * Supports account abstraction for XRPL-integrated user operations.
 */
contract PersonalAccount is
    IIPersonalAccount, ReentrancyGuardTransient,
    ERC721Holder, ERC1155Holder, IERC1363Receiver
{
    using SafeERC20 for IERC20;

    address private constant EMPTY_ADDRESS = 0x0000000000000000000000000000000000001111;

    /// @notice MasterAccountController contract address
    address public controllerAddress;
    /// @notice XRPL address
    string public xrplOwner;

    modifier onlyController() {
        require(msg.sender == controllerAddress, OnlyController());
        _;
    }

    constructor() {
        // ensure the implementation contract itself cannot be initialized/used
        controllerAddress = EMPTY_ADDRESS;
    }

    receive() external payable {}

    /**
     * Proxyable initialization method. Can be called only once, from the proxy constructor
     * @param _controllerAddress MasterAccountController contract address
     * @param _xrplOwner XRPL address owner
     * @dev initialize is callable once by anyone (proxy constructor in practice)
     */
    function initialize(
        address _controllerAddress,
        string calldata _xrplOwner
    ) external {
        require(controllerAddress == address(0), AlreadyInitialized());
        require(_controllerAddress != address(0), InvalidControllerAddress());
        require(bytes(_xrplOwner).length > 0, InvalidXrplOwner());

        controllerAddress = _controllerAddress;
        xrplOwner = _xrplOwner;
    }

    /// @inheritdoc IIPersonalAccount
    function reserveCollateral(
        address _agentVault,
        uint256 _lots,
        address payable _executor,
        uint256 _executorFee
    )
        external payable
        onlyController nonReentrant
        returns (uint256 _collateralReservationId)
    {
        IAssetManager assetManager = ContractRegistry.getAssetManagerFXRP();

        // Check agent vault status
        AgentInfo.Info memory agentInfo = assetManager.getAgentInfo(_agentVault);
        require(agentInfo.status == AgentInfo.Status.NORMAL, AgentNotAvailable());

        // Check fees
        uint256 collateralReservationFee = assetManager.collateralReservationFee(_lots);
        require(
            msg.value >= collateralReservationFee + _executorFee,
            InsufficientFundsForCollateralReservation(collateralReservationFee, _executorFee)
        );

        // Reserve collateral
        _collateralReservationId = assetManager.reserveCollateral{value: msg.value}(
            _agentVault,
            _lots,
            agentInfo.feeBIPS,
            _executor
        );
        assert(_collateralReservationId > 0);
        emit CollateralReserved(
            _agentVault,
            _lots,
            _executor,
            _executorFee,
            _collateralReservationId
        );
    }

    /// @inheritdoc IIPersonalAccount
    function transferFXrp(
        address _to,
        uint256 _amount
    )
        external
        onlyController nonReentrant
    {
        IERC20 fxrp = ContractRegistry.getAssetManagerFXRP().fAsset();
        fxrp.safeTransfer(_to, _amount);
        emit FXrpTransferred(_to, _amount);
    }

    /// @inheritdoc IIPersonalAccount
    function redeemFXrp(
        uint256 _lots,
        address payable _executor,
        uint256 _executorFee
    )
        external payable
        onlyController nonReentrant
        returns (uint256 _amount)
    {
        require(msg.value >= _executorFee, InsufficientFundsForRedeem(_executorFee));
        IAssetManager assetManager = ContractRegistry.getAssetManagerFXRP();
        _amount = assetManager.redeem{value: msg.value}(
            _lots,
            xrplOwner,
            _executor
        );
        emit FXrpRedeemed(_lots, _amount, _executor, _executorFee);
    }

    /// @inheritdoc IIPersonalAccount
    function deposit(
        IVaultsFacet.VaultType _vaultType,
        address _vault,
        uint256 _assets
    )
        external
        onlyController nonReentrant
        returns (uint256 _shares)
    {
        assert(
            _vaultType == IVaultsFacet.VaultType.Firelight ||
            _vaultType == IVaultsFacet.VaultType.Upshift
        );
        IERC20 fxrp = ContractRegistry.getAssetManagerFXRP().fAsset();
        require(fxrp.approve(_vault, _assets), ApprovalFailed());
        emit Approved(address(fxrp), _vault, _assets);

        if (_vaultType == IVaultsFacet.VaultType.Firelight) {
            _shares = IIVault(_vault).deposit(_assets, address(this));
        } else {
            _shares = IIVault(_vault).deposit(address(fxrp), _assets, address(this));
        }
        emit Deposited(_vault, _assets, _shares);
    }

    /// @inheritdoc IIPersonalAccount
    function redeem(
        address _vault,
        uint256 _shares
    )
        external
        onlyController nonReentrant
        returns (uint256 _assets)
    {
        _assets = IIVault(_vault).redeem(
            _shares,
            address(this),
            address(this)
        );
        emit Redeemed(_vault, _assets, _shares);
    }

    /// @inheritdoc IIPersonalAccount
    function claimWithdraw(
        address _vault,
        uint256 _period
    )
        external
        onlyController nonReentrant
        returns (uint256 _assets)
    {
        _assets = IIVault(_vault).claimWithdraw(_period);
        emit WithdrawalClaimed(_vault, _period, _assets);
    }

    /// @inheritdoc IIPersonalAccount
    function requestRedeem(
        address _vault,
        uint256 _shares
    )
        external
        onlyController nonReentrant
        returns (uint256 _claimableEpoch, uint256 _year, uint256 _month, uint256 _day)
    {
        address lpToken = IIVault(_vault).lpTokenAddress();
        IERC20(lpToken).forceApprove(_vault, _shares);
        emit Approved(lpToken, _vault, _shares);
        (_claimableEpoch, _year, _month, _day) = IIVault(_vault).requestRedeem(
            _shares,
            address(this)
        );
        emit RedeemRequested(_vault, _shares, _claimableEpoch, _year, _month, _day);
    }

    /// @inheritdoc IIPersonalAccount
    function claim(
        address _vault,
        uint256 _year,
        uint256 _month,
        uint256 _day
    )
        external
        onlyController nonReentrant
        returns (uint256 _shares, uint256 _assets)
    {
        (_shares, _assets) = IIVault(_vault).claim(
            _year,
            _month,
            _day,
            address(this)
        );
        emit Claimed(_vault, _year, _month, _day, _shares, _assets);
    }

    /// @inheritdoc IPersonalAccount
    function executeUserOp(
        IPersonalAccount.Call[] calldata _calls
    )
        external payable
        onlyController nonReentrant
    {
        for (uint256 i = 0; i < _calls.length; i++) {
            (bool success, bytes memory result) = _calls[i].target.call{
                value: _calls[i].value
            }(_calls[i].data);
            if (!success) {
                revert CallFailed(i, result);
            }
        }
    }

    /// @inheritdoc IPersonalAccount
    function implementation() external view returns (address) {
        // controller is the beacon
        return IBeacon(controllerAddress).implementation();
    }

    /// @inheritdoc IERC1363Receiver
    function onTransferReceived(
        address,
        address,
        uint256,
        bytes calldata
    )
        external pure
        returns (bytes4)
    {
        return IERC1363Receiver.onTransferReceived.selector;
    }

    /// @inheritdoc IERC165
    function supportsInterface(
        bytes4 _interfaceId
    )
        public view
        override(ERC1155Holder)
        returns (bool)
    {
        return
            _interfaceId == type(IERC721Receiver).interfaceId ||
            _interfaceId == type(IERC1363Receiver).interfaceId ||
            super.supportsInterface(_interfaceId); // ERC1155Holder covers IERC1155Receiver and IERC165
    }
}

contracts/smartAccounts/interface/IIPers.content:
// SPDX-License-Identifier: MIT
pragma solidity >=0.7.6 <0.9;

import {IPersonalAccount} from "../../userInterfaces/IPersonalAccount.sol";
import {IVaultsFacet} from "../../userInterfaces/facets/IVaultsFacet.sol";


/**
 * @title IIPersonalAccount
 * @notice Internal interface for PersonalAccount contract.
 */
interface IIPersonalAccount is IPersonalAccount {

    /**
     * @notice Reserve collateral for minting operation.
     * @param _agentVault Agent vault address.
     * @param _lots Number of lots to mint.
     * @param _executor Executor address.
     * @param _executorFee Executor fee to be paid.
     * @return _collateralReservationId The ID of the collateral reservation.
     */
    function reserveCollateral(
        address _agentVault,
        uint256 _lots,
        address payable _executor,
        uint256 _executorFee
    )
        external payable
        returns (uint256 _collateralReservationId);

    /**
     * @notice Transfer FXRP to another address.
     * @param _to Recipient address.
     * @param _amount Amount of FXRP to transfer.
     */
    function transferFXrp(
        address _to,
        uint256 _amount
    )
        external;

    /**
     * @notice Redeem FXRP and receive XRP.
     * @param _lots Number of lots to redeem.
     * @param _executor Executor address.
     * @param _executorFee Executor fee to be paid.
     * @return _amount The actual amount of FXRP redeemed.
     */
    function redeemFXrp(
        uint256 _lots,
        address payable _executor,
        uint256 _executorFee
    )
        external payable
        returns (uint256 _amount);

    /**
     * @notice Deposit assets into the vault.
     * @param _vaultType The type of the vault.
     * @param _vault Vault address.
     * @param _assets The amount of assets to deposit.
     * @return _shares The received shares.
     */
    function deposit(
        IVaultsFacet.VaultType _vaultType,
        address _vault,
        uint256 _assets
    )
        external
        returns (uint256 _shares);

    /**
     * @notice Redeem shares from the vault.
     * @param _vault Vault address.
     * @param _shares The amount of shares to redeem.
     * @return _assets The amount of assets redeemed.
     */
    function redeem(
        address _vault,
        uint256 _shares
    )
        external
        returns (uint256 _assets);

    /**
     * @notice Claim withdrawal assets from the vault.
     * @param _vault Vault address.
     * @param _period Period to claim.
     * @return _assets The amount of assets claimed.
     */
    function claimWithdraw(
        address _vault,
        uint256 _period
    )
        external
        returns (uint256 _assets);

    /**
     * @notice Request redemption of shares from the vault.
     * @param _vault Vault address.
     * @param _shares Number of shares to redeem.
     * @return _claimableEpoch The epoch when the assets can be claimed.
     * @return _year The year of the claimable date.
     * @return _month The month of the claimable date.
     * @return _day The day of the claimable date.
     */
    function requestRedeem(
        address _vault,
        uint256 _shares
    )
        external
        returns (uint256 _claimableEpoch, uint256 _year, uint256 _month, uint256 _day);

    /**
     * @notice Claim requested redeemed shares for a specific date from the vault.
     * @param _vault Vault address.
     * @param _year Year of the claim date.
     * @param _month Month of the claim date.
     * @param _day Day of the claim date.
     * @return _shares The number of shares claimed.
     * @return _assets The amount of assets claimed.
     */
    function claim(
        address _vault,
        uint256 _year,
        uint256 _month,
        uint256 _day
    )
        external
        returns (uint256 _shares, uint256 _assets);

}

contracts/smartAccounts/interface/IIVaul.content:
// SPDX-License-Identifier: MIT
pragma solidity >=0.7.6 <0.9;

// ERC4626-compatible vault
interface IIVault {

    // Firelight
    function deposit(
        uint256 _assets,
        address _receiver
    )
        external
        returns (uint256 _shares);

    // Firelight
    function redeem(
        uint256 _shares,
        address _receiver,
        address _owner
    )
        external
        returns (uint256 _assets);

    // Firelight
    function claimWithdraw(
        uint256 _period
    )
        external
        returns (uint256 _assets);

    // Upshift
    function deposit(
        address _assetIn,
        uint256 _amountIn,
        address _receiverAddr
    )
        external
        returns (uint256 _shares);

    // Upshift
    function requestRedeem(
        uint256 _shares,
        address _receiverAddr
    )
        external
        returns (uint256 _claimableEpoch, uint256 _year, uint256 _month, uint256 _day);

    // Upshift
    function claim(
        uint256 _year,
        uint256 _month,
        uint256 _day,
        address _receiverAddr
    )
        external
        returns (uint256 _shares, uint256 _assetsAfterFee);

    // Upshift
    function previewRedemption(
        uint256 _shares,
        bool _isInstant
    )
        external
        view
        returns (uint256 _assetsAmount, uint256 _assetsAfterFee);

    // Upshift
    function lpTokenAddress()
        external
        view
        returns (address);

}

contracts/userInterfaces/IFAssetRedeemCo.content:
// SPDX-License-Identifier: MIT
pragma solidity >=0.8.4 <0.9;

import {IOwnableWithTimelock} from "./IOwnableWithTimelock.sol";
import {IAssetManager} from "flare-periphery/src/flare/IAssetManager.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IBeacon} from "@openzeppelin/contracts/proxy/beacon/IBeacon.sol";
import {ILayerZeroComposer} from "@layerzerolabs/lz-evm-protocol-v2/contracts/interfaces/ILayerZeroComposer.sol";

/**
 * @title IFAssetRedeemComposer
 * @notice User interface for the LayerZero compose-based FAsset redeem orchestrator.
 * @dev Integration requirement for source-chain callers: `lzCompose` enforces
 * `msg.value >= RedeemComposeMessage.executorFee`; `send` does not. Callers must therefore
 * configure the `lzComposeOption` with a compose value of at least `executorFee`, or the
 * LayerZero executor may be under-incentivized to deliver `lzCompose` with the intended
 * `msg.value`, leaving the message unexecuted.
 */
interface IFAssetRedeemComposer is ILayerZeroComposer, IBeacon, IOwnableWithTimelock {

    /**
     * @notice Struct representing the LZ compose message for f-asset redemption.
     */
    struct RedeemComposeMessage {
        /// @notice EVM address that owns the per-redeemer account.
        address redeemer;
        /// @notice Underlying-chain redemption destination passed to the asset manager.
        string redeemerUnderlyingAddress;
        /// @notice Indicates whether to call `redeemWithTag` or `redeemAmount` on the asset manager.
        /// If true, asset manager must support it (checks `redeemWithTagSupported` - enabled only for XRP).
        bool redeemWithTag;
        /// @notice Destination tag. Only used if `redeemWithTag` is true.
        /// Only for XRP; it must fit in 32 bits for now.
        uint256 destinationTag;
        /// @notice Executor address used for redemption. If zero, default executor is used.
        address payable executor;
        /// @notice Executor fee (in wei) to be paid to the executor for executing the redeem on Flare.
        /// @dev `lzCompose` enforces `msg.value >= executorFee`; `send` does not. Callers must
        /// therefore configure the `lzComposeOption` with a compose value of at least `executorFee`,
        /// or the LayerZero executor may be under-incentivized to deliver `lzCompose` with the
        /// intended `msg.value`, leaving the message unexecuted.
        uint256 executorFee;
    }

    /**
     * @notice Token address and balance pair.
     */
    struct TokenBalance {
        /// @notice Token address.
        address token;
        /// @notice Token balance.
        uint256 balance;
    }

    /**
     * @notice Struct representing the balances of a redeemer account.
     */
    struct AccountBalances {
        /// @notice f-asset token and balance.
        TokenBalance fAsset;
        /// @notice Stable coin token and balance.
        TokenBalance stableCoin;
        /// @notice Wrapped native token and balance.
        TokenBalance wNat;
    }

    /**
     * @notice Emitted when the account beacon implementation is updated.
     * @param implementation New redeemer account implementation address.
     */
    event RedeemerAccountImplementationSet(address indexed implementation);

    /**
     * @notice Emitted when a redeem call succeeds.
     * @param guid LayerZero message GUID.
     * @param srcEid Source endpoint ID.
     * @param redeemer Redeemer account owner address.
     * @param redeemerAccount Deterministic redeemer account address.
     * @param amountToRedeemUBA Amount to redeem in UBA.
     * @param redeemerUnderlyingAddress Underlying destination address for redeem.
     * @param redeemWithTag Indicates whether `redeemWithTag` or `redeemAmount` was called on the asset manager.
     * @param destinationTag Destination tag used for redeem, if applicable.
     * @param executor Executor address used for redeem.
     * @param executorFee Executor fee passed with compose message.
     * @param redeemedAmountUBA Amount redeemed in UBA reported by asset manager.
     * @param wrappedAmount Amount of wrapped native tokens deposited to redeemer account.
     */
    event FAssetRedeemed(
        bytes32 indexed guid,
        uint32 indexed srcEid,
        address indexed redeemer,
        address redeemerAccount,
        uint256 amountToRedeemUBA,
        string redeemerUnderlyingAddress,
        bool redeemWithTag,
        uint256 destinationTag,
        address executor,
        uint256 executorFee,
        uint256 redeemedAmountUBA,
        uint256 wrappedAmount
    );

    /**
     * @notice Emitted when redeem call fails but token transfer to redeemer account already happened.
     * @param guid LayerZero message GUID.
     * @param srcEid Source endpoint ID.
     * @param redeemer Redeemer account owner address.
     * @param redeemerAccount Deterministic redeemer account address.
     * @param amountToRedeemUBA Amount to redeem in UBA.
     * @param wrappedAmount Amount of wrapped native tokens deposited to redeemer account in case of failure.
     */
    event FAssetRedeemFailed(
        bytes32 indexed guid,
        uint32 indexed srcEid,
        address indexed redeemer,
        address redeemerAccount,
        uint256 amountToRedeemUBA,
        uint256 wrappedAmount
    );

    /**
     * @notice Emitted when a new redeemer account is created.
     * @param redeemer Redeemer account owner address.
     * @param account Newly created deterministic account address.
     */
    event RedeemerAccountCreated(address indexed redeemer, address indexed account);

    /**
     * @notice Emitted when owner manually transfers f-asset from composer.
     * @param to Recipient account.
     * @param amount Amount transferred.
     */
    event FAssetTransferred(address indexed to, uint256 amount);

    /**
     * @notice Emitted when default executor is set.
     * @param executor Executor address used for redemption.
     */
    event DefaultExecutorSet(address executor);

    /**
     * @notice Emitted when default composer fee is updated.
     * @param defaultComposerFeePPM New default composer fee in PPM.
     */
    event DefaultComposerFeeSet(uint256 defaultComposerFeePPM);

    /**
     * @notice Emitted when srcEid-specific composer fee is set.
     * @param srcEid OFT source endpoint ID.
     * @param composerFeePPM Composer fee in PPM for the specified srcEid.
     */
    event ComposerFeeSet(uint32 indexed srcEid, uint256 composerFeePPM);

    /**
     * @notice Emitted when srcEid-specific composer fee override is removed.
     * @param srcEid OFT source endpoint ID.
     */
    event ComposerFeeRemoved(uint32 indexed srcEid);

    /**
     * @notice Emitted when composer fee recipient is updated.
     * @param composerFeeRecipient New fee recipient address.
     */
    event ComposerFeeRecipientSet(address indexed composerFeeRecipient);

    /**
     * @notice Emitted when composer fee is collected in fAsset.
     * @param guid LayerZero message GUID.
     * @param srcEid Source endpoint ID.
     * @param composerFeeRecipient Recipient of collected composer fee.
     * @param composerFee Collected composer fee amount in fAsset units.
     */
    event ComposerFeeCollected(
        bytes32 indexed guid,
        uint32 indexed srcEid,
        address indexed composerFeeRecipient,
        uint256 composerFee
    );

    /**
     * @notice Reverts when a required address argument is zero.
     */
    error InvalidAddress();

    /**
    * @notice Reverts when the provided executor fee is insufficient for redemption execution.
    */
    error InsufficientExecutorFee(uint256 providedFee, uint256 requiredFee);

    /**
     * @notice Reverts when caller is not the LayerZero endpoint.
     */
    error OnlyEndpoint();

    /**
     * @notice Reverts when compose message source OApp is unexpected.
     * @param from Untrusted source OApp address.
     */
    error InvalidSourceOApp(address from);

    /**
     * @notice Reverts when redeemer account implementation address has no code.
     */
    error InvalidRedeemerAccountImplementation();

    /**
     * @notice Reverts when composer fee PPM is invalid.
     */
    error InvalidComposerFeePPM();

    /**
     * @notice Reverts when composer fee for a srcEid is not set but expected.
     * @param srcEid OFT source endpoint ID.
     */
    error ComposerFeeNotSet(uint32 srcEid);

    /**
     * @notice Reverts when composer fee recipient address is invalid.
     */
    error InvalidComposerFeeRecipient();

    /**
     * @notice Reverts when array lengths do not match.
     */
    error LengthMismatch();

    /**
     * @notice Returns trusted endpoint that may call `lzCompose`.
     * @return Endpoint address.
     */
    function endpoint() external view returns (address);

    /**
     * @notice Returns trusted source OApp.
     * @return Source OApp address.
     */
    function trustedSourceOApp() external view returns (address);

    /**
     * @notice Returns configured asset manager contract.
     * @return Asset manager instance.
     */
    function assetManager() external view returns (IAssetManager);

    /**
     * @notice Returns configured f-asset token.
     * @return F-asset token instance.
     */
    function fAsset() external view returns (IERC20);

    /**
     * @notice Returns configured stable coin used for allowance priming in redeemer accounts.
     * @return Stable coin token.
     */
    function stableCoin() external view returns (IERC20);

    /**
     * @notice Returns configured wrapped native token used for allowance priming in redeemer accounts.
     * @return Wrapped native token.
     */
    function wNat() external view returns (IERC20);

    /**
     * @notice Returns current redeemer account beacon implementation.
     * @return Redeemer account implementation address.
     */
    function redeemerAccountImplementation() external view returns (address);

    /**
     * @notice Returns recipient of collected composer fee.
     * @return Composer fee recipient address.
     */
    function composerFeeRecipient() external view returns (address);

    /**
     * @notice Returns default composer fee in PPM.
     * @return Default composer fee in PPM.
     */
    function defaultComposerFeePPM() external view returns (uint256);

    /**
     * @notice Returns default executor address used for redemption execution.
     * @return Default executor address.
     */
    function defaultExecutor() external view returns (address payable);

    /**
     * @notice Returns composer fee in PPM for the given OFT source endpoint.
     * @param _srcEid OFT source endpoint ID.
     * @return _composerFeePPM Composer fee in PPM.
     */
    function getComposerFeePPM(
        uint32 _srcEid
    )
        external
        view
        returns (uint256 _composerFeePPM);

    /**
     * @notice Returns deterministic redeemer account address for owner.
     * @param _redeemer Redeemer account owner address.
     * @return Deterministic account address.
     */
    function getRedeemerAccountAddress(
        address _redeemer
    )
        external view
        returns (address);

    /**
     * @notice Checks if the given account is the deterministic redeemer account for its owner.
     * @param _address The Flare address to check.
     * @return _isRedeemerAccount True if the address is a redeemer account, false otherwise.
     * @return _owner Redeemer account owner address if it is a redeemer account, zero address otherwise.
     */
    function isRedeemerAccount(
        address _address
    )
        external view
        returns (bool _isRedeemerAccount, address _owner);

    /**
     * @notice Returns the balances of an account for f-asset, stable coin, and wrapped native token.
     * @param _account The address (can be a redeemer account or any other address) for which to retrieve balances.
     * @return _balances The account balances.
     */
    function getBalances(
        address _account
    )
        external view
        returns (AccountBalances memory _balances);
}

contracts/userInterfaces/IFAssetRedeemer.content:
// SPDX-License-Identifier: MIT
pragma solidity >=0.8.4 <0.9;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IReferencedPaymentNonexistence} from "flare-periphery/src/flare/IReferencedPaymentNonexistence.sol";
import {IXRPPaymentNonexistence} from "flare-periphery/src/flare/IXRPPaymentNonexistence.sol";

/**
 * @title IFAssetRedeemerAccount
 * @notice User interface for per-redeemer account operations.
 */
interface IFAssetRedeemerAccount {

    /**
     * @notice Emitted when a redeem call succeeds.
     * @param amountToRedeemUBA Amount to redeem in UBA.
     * @param redeemerUnderlyingAddress Underlying destination address for redeem.
     * @param redeemWithTag Indicates whether `redeemWithTag` or `redeemAmount` was called on the asset manager.
     * @param destinationTag Destination tag used for redeem, if applicable.
     * @param executor Executor address used for redeem.
     * @param executorFee Executor fee passed with compose message.
     * @param redeemedAmountUBA Amount redeemed in UBA reported by asset manager.
     */
    event FAssetRedeemed(
        uint256 amountToRedeemUBA,
        string redeemerUnderlyingAddress,
        bool redeemWithTag,
        uint256 destinationTag,
        address executor,
        uint256 executorFee,
        uint256 redeemedAmountUBA
    );

    /**
     * @notice Emitted when allowances are set to max from account to owner.
     * @param owner Owner of redeemer account.
     * @param fAsset FAsset token.
     * @param stableCoin Stable coin token.
     * @param wNat Wrapped native token.
     */
    event MaxAllowancesSet(
        address indexed owner,
        IERC20 fAsset,
        IERC20 stableCoin,
        IERC20 wNat
    );

    /**
     * @notice Emitted when the owner triggers `redemptionPaymentDefault` on the asset manager.
     * @param redemptionRequestId Redemption request id passed to the asset manager.
     */
    event RedemptionPaymentDefaulted(uint256 indexed redemptionRequestId);

    /**
     * @notice Emitted when the owner triggers `xrpRedemptionPaymentDefault` on the asset manager.
     * @param redemptionRequestId Redemption request id passed to the asset manager.
     */
    event XrpRedemptionPaymentDefaulted(uint256 indexed redemptionRequestId);

    /**
     * @notice Reverts when a required address is zero.
     */
    error InvalidAddress();

    /**
     * @notice Reverts when caller is not the composer.
     */
    error ComposerOnly();

    /**
     * @notice Reverts when caller is not the account owner.
     */
    error OwnerOnly();

    /**
     * @notice Reverts when initialize is called more than once.
     */
    error AlreadyInitialized();

    /**
     * @notice Reverts when redeem with tag is attempted on asset manager that does not support it.
     */
    error RedeemWithTagNotSupported();

    /**
     * @notice Triggers `redemptionPaymentDefault` on the asset manager for a redemption initiated
     *         by this account. Can only be called by the account owner.
     * @dev Asset manager is read from the composer; reverts bubble up to the caller.
     * @param _proof Proof of non-payment with correct payment reference on the underlying chain.
     * @param _redemptionRequestId Id of an existing redemption request initiated by this account.
     */
    function redemptionPaymentDefault(
        IReferencedPaymentNonexistence.Proof calldata _proof,
        uint256 _redemptionRequestId
    )
        external;

    /**
     * @notice Triggers XRP-specific variant of `redemptionPaymentDefault`.
     *         Can only be called by the account owner.
     * @dev Asset manager is read from the composer; reverts bubble up to the caller.
     * @param _proof Proof of non-payment on the XRP chain.
     * @param _redemptionRequestId Id of an existing redemption request initiated by this account.
     */
    function xrpRedemptionPaymentDefault(
        IXRPPaymentNonexistence.Proof calldata _proof,
        uint256 _redemptionRequestId
    )
        external;

    /**
     * @notice Returns the owner of the redeemer account.
     * @return The address of the owner.
     */
    function owner() external view returns (address);

    /**
     * @notice Returns the composer associated with the redeemer account.
     * @return The address of the composer.
     */
    function composer() external view returns (address);
}

